grep -h "🧭" ~/.pm2/logs/pool-out.log | sed -E "s/.*🧭 (heavy|light)[^:]*: target [0-9]+, candidates ([0-9]+), at target ([0-9]+), within 1 ([0-9]+).*/\1 \2 \3 \4/" | awk '{k=$1; n[k]++; c[k]+=$2; t[k]+=$3; w[k]+=$4; if ($2>1 && $3==1) one[k]++} END {for (k in n) printf "%s: %d decisions, avg candidates %.2f, avg at target %.2f, avg within 1 %.2f, only 1 at target (of >1): %.0f%%\n", k, n[k], c[k]/n[k], t[k]/n[k], w[k]/n[k], 100*one[k]/n[k]}'
